<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><section class="auth-shell"><div class="container"><div class="auth-card"><p class="eyebrow">Protected workspace</p><h1>Welcome back</h1><p class="text-secondary mb-4">Sign in with your staff account.</p><form action="<?= site_url('login') ?>" method="post" novalidate><?= csrf_field() ?><?php $errors=session('errors')??[]; ?><div class="mb-3"><label class="form-label" for="username">Username</label><input class="form-control <?= isset($errors['username'])?'is-invalid':'' ?>" id="username" name="username" maxlength="50" autocomplete="username" value="<?= esc(old('username')) ?>" required><?php if(isset($errors['username'])): ?><div class="invalid-feedback"><?= esc($errors['username']) ?></div><?php endif; ?></div><div class="mb-4"><label class="form-label" for="password">Password</label><input class="form-control <?= isset($errors['password'])?'is-invalid':'' ?>" id="password" type="password" name="password" maxlength="255" autocomplete="current-password" required><?php if(isset($errors['password'])): ?><div class="invalid-feedback"><?= esc($errors['password']) ?></div><?php endif; ?></div><button class="btn btn-accent w-100" type="submit">Sign in</button></form></div></div></section><?= $this->endSection() ?>
